-- ============================================================================
-- B5 FOLLOW-ON W4a (typed-case panel modes): cementing.
--
-- Plan of record: docs/graded-field-audit/FOLLOW-ON-PROGRAMME.md section 1
-- route (b), and docs/graded-field-audit/w4a/cementing.json. Owner approved D1
-- to D7 as recommended, 2026-09-21 (D2: the panel guard forbids a DEFAULT
-- state that lands on a graded answer; typing the case is the work).
--
-- INTERMEDIATE
--   The placement march and both rate bisections are engine-only, and the
--   placement explorer ran only the two published jobs. W4a adds a Your job view
--   with a box for every input of a lead-and-tail placement (opening on the
--   lessons' slant job), run through jobVolumes and simulatePlacement with both
--   edges bisected. The brief now names the view. Prompt only.
--   PROMPT was: Six placement numbers for the Associate capstone's job.
--   PROMPT now: Six placement numbers for the Associate capstone's job. Type
--   that job, with the fluids, Fann sets, rate and limit below, into the
--   placement explorer's Your job view.
--
-- WHAT DOES NOT MOVE. `fields` (every key, label, unit, expected and
-- tolerance), title, dataset, status and the row. The guard requires `fields`
-- to equal its live value exactly, before and after.
--
-- ATTEMPTS. Prompt copy only: no graded key or tolerance moves, so no attempt
-- can be graded differently and there is no attempts guard.
--
-- GUARDS. Each row must hold EITHER its live prompt (by md5) and fields (exact
-- jsonb) as the W1-state scratch replay has them (it is rewritten), OR its W4a
-- form (left alone). Anything else raises and the whole file rolls back. A
-- file that will write first checks that W1 is applied and refuses without it.
-- Generated by docs/graded-field-audit/w4a_capstones.py. SAFE TO RE-RUN: a
-- second run writes nothing.
-- ============================================================================

do $$
declare
  v_n        integer;
  v_count    integer;
  v_written  integer := 0;
  v_s0       text;
begin
  -- cementing / intermediate
  select count(*) into v_n from public.academy_capstones where app_slug = 'cementing' and tier = 'intermediate' and active;
  if v_n <> 1 then raise exception 'w4a cementing refused: cementing/intermediate has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '1bdeb65f413b8b04af8a38e378dc7607' and fields = '[{"key": "end_pump_pressure_pa", "tol": 50, "unit": "Pa", "label": "End pump pressure", "expected": 6233731.747831926}, {"key": "float_diff_pa", "tol": 50, "unit": "Pa", "label": "Float differential", "expected": 4969584.9998046905}, {"key": "max_ecd_prev_shoe_kgm3", "tol": 0.005, "unit": "kg/m3", "label": "Peak ECD, previous shoe", "expected": 1576.3692813689117}, {"key": "min_rate_no_free_fall_m3s", "tol": 5E-7, "unit": "m3/s", "label": "Slowest rate, no free fall", "expected": 0.12974748005989847}, {"key": "max_rate_under_ecd_limit_m3s", "tol": 5E-7, "unit": "m3/s", "label": "Fastest rate under 1600", "expected": 0.04354109120904704}, {"key": "rate_window_width_m3s", "tol": 5E-7, "unit": "m3/s", "label": "Rate window width", "expected": -0.08620638885085144}]'::jsonb then 'old'
              when md5(prompt) = 'e8236e9f346a022f954cae51a6a02bed' and fields = '[{"key": "end_pump_pressure_pa", "tol": 50, "unit": "Pa", "label": "End pump pressure", "expected": 6233731.747831926}, {"key": "float_diff_pa", "tol": 50, "unit": "Pa", "label": "Float differential", "expected": 4969584.9998046905}, {"key": "max_ecd_prev_shoe_kgm3", "tol": 0.005, "unit": "kg/m3", "label": "Peak ECD, previous shoe", "expected": 1576.3692813689117}, {"key": "min_rate_no_free_fall_m3s", "tol": 5E-7, "unit": "m3/s", "label": "Slowest rate, no free fall", "expected": 0.12974748005989847}, {"key": "max_rate_under_ecd_limit_m3s", "tol": 5E-7, "unit": "m3/s", "label": "Fastest rate under 1600", "expected": 0.04354109120904704}, {"key": "rate_window_width_m3s", "tol": 5E-7, "unit": "m3/s", "label": "Rate window width", "expected": -0.08620638885085144}]'::jsonb then 'new'
              else 'other' end
    into v_s0 from public.academy_capstones where app_slug = 'cementing' and tier = 'intermediate' and active;
  if v_s0 = 'other' then
    raise exception 'w4a cementing refused: cementing/intermediate matches neither its live form (prompt md5 1bdeb65f413b8b04af8a38e378dc7607) nor its W4a form (prompt md5 e8236e9f346a022f954cae51a6a02bed), with the fields this file was generated against';
  end if;

  -- nothing to write: every row is already in its W4a form
  if v_s0 = 'new' then
    raise notice 'w4a cementing: 0 of 1 row(s) written, all already applied';
    return;
  end if;

  -- W1 (20261024a/b) must be applied first: its rows are this file's base
  if exists (select 1 from public.academy_capstones where app_slug = 'rodpump' and tier = 'beginner' and active and md5(prompt) = '27fc6852586864af77f23cdbbf2deacc')
     or exists (select 1 from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
                 where c.app_slug = 'petrophysics' and c.tier = 'advanced' and c.active and f->>'key' = 'sw_waterleg_mean'
                   and (f->>'tol')::float8 = 0.005) then
    raise exception 'w4a cementing refused: W1 (20261024a/b) is not applied on this database; apply it first (/root/w1-apply/apply.sh apply --prod)';
  end if;

  if v_s0 = 'old' then
    update public.academy_capstones
       set prompt = 'Six placement numbers for the Associate capstone''s job. Type that job, with the fluids, Fann sets, rate and limit below, into the placement explorer''s Your job view. Mud in the hole at 1400 kg/m3, then 6 cubic metres of spacer at 1520, the lead at 1580, the tail at 1920, and displacement at 1400. Four NEW Fann sets: mud 600/300/6/3 of 72, 44, 8 and 7; spacer 46, 28, 5 and 4; lead 90, 56, 12 and 9; tail 124, 78, 17 and 14. Pump rate 0.028 cubic metres a second. The previous shoe at 350 m has been leak-off tested to 1600 kg/m3 equivalent. Report: (1) the END PUMP PRESSURE in pascals; (2) the FLOAT DIFFERENTIAL in pascals; (3) the PEAK ECD AT THE PREVIOUS SHOE in kg/m3; (4) the SMALLEST pump rate at which the job does NOT free fall, in cubic metres a second; (5) the LARGEST pump rate whose peak ECD at the previous shoe stays at or below 1600; and (6) the RATE WINDOW WIDTH, which is field 5 less field 4. Traps. Field 3 is at the PREVIOUS shoe at 350 m, not at the casing shoe at 1400, and the engine reports both. Fields 4 and 5 are BISECTIONS: a sweep will put you a whole step wide. Field 6 is NEGATIVE, because this job''s window is CLOSED, and a positive answer means one of the two edges is wrong. Field 4 is about five times the design rate, which is not an error: large-diameter casing in a wide annulus free falls at every rate anybody could pump. And the four Fann sets are what both edges are made of, so reusing the lessons'' rheologies moves both. Free checks: field 5 less field 4 is field 6 exactly; field 3 must be BELOW 1600 and field 5 must therefore exceed the design rate of 0.028; and field 1 must exceed field 2, because their difference is the friction at the last step.'
     where app_slug = 'cementing' and tier = 'intermediate' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w4a cementing refused: cementing/intermediate updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = 'e8236e9f346a022f954cae51a6a02bed' and fields = '[{"key": "end_pump_pressure_pa", "tol": 50, "unit": "Pa", "label": "End pump pressure", "expected": 6233731.747831926}, {"key": "float_diff_pa", "tol": 50, "unit": "Pa", "label": "Float differential", "expected": 4969584.9998046905}, {"key": "max_ecd_prev_shoe_kgm3", "tol": 0.005, "unit": "kg/m3", "label": "Peak ECD, previous shoe", "expected": 1576.3692813689117}, {"key": "min_rate_no_free_fall_m3s", "tol": 5E-7, "unit": "m3/s", "label": "Slowest rate, no free fall", "expected": 0.12974748005989847}, {"key": "max_rate_under_ecd_limit_m3s", "tol": 5E-7, "unit": "m3/s", "label": "Fastest rate under 1600", "expected": 0.04354109120904704}, {"key": "rate_window_width_m3s", "tol": 5E-7, "unit": "m3/s", "label": "Rate window width", "expected": -0.08620638885085144}]'::jsonb) from public.academy_capstones where app_slug = 'cementing' and tier = 'intermediate' and active) is not true then
    raise exception 'w4a cementing refused: cementing/intermediate does not read back as its W4a form';
  end if;

  raise notice 'w4a cementing: % of 1 row(s) written, % already applied', v_written, 1 - v_written;
end $$;
